}

import * as fs from 'fs';
import * as path from 'path';

export interface FileCoverage {
    filePath: string;
    coverage: number;
    details?: string;
}

export class CoverageParser {
    static parseJest(jsonPath: string): FileCoverage[] {
        if (!fs.existsSync(jsonPath)) return [];
        const data = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
        const results: FileCoverage[] = [];

        for (const filePath in data) {
            const summary = data[filePath].s;
            const total = Object.keys(summary).length;
            const covered = Object.values(summary).filter((count: any) => count > 0).length;
            const percentage = total === 0 ? 100 : (covered / total) * 100;

            // Normalize path: Convert absolute path to relative path if possible
            let normalizedPath = filePath;
            if (path.isAbsolute(filePath) && filePath.includes(process.cwd())) {
                normalizedPath = path.relative(process.cwd(), filePath);
            }

            results.push({ filePath: normalizedPath, coverage: percentage });
        }
        return results;
    }

    static parseGo(outPath: string): FileCoverage[] {
        if (!fs.existsSync(outPath)) return [];
        const content = fs.readFileSync(outPath, 'utf8');
        const lines = content.split('\n');
        const fileData: Record<string, { covered: number; total: number; missingBlocks: string[] }> = {};

        for (const line of lines) {
            if (line.startsWith('mode:') || !line.trim()) continue;
            const parts = line.split(' ');
            if (parts.length < 3) continue;

            const fileLine = parts[0];
            const fileName = fileLine.split(':')[0];
            const range = fileLine.split(':')[1];
            const statements = parseInt(parts[1], 10);
            const count = parseInt(parts[2], 10);

            if (!fileData[fileName]) fileData[fileName] = { covered: 0, total: 0, missingBlocks: [] };
            fileData[fileName].total += statements;
            if (count > 0) {
                fileData[fileName].covered += statements;
            } else {
                fileData[fileName].missingBlocks.push(range);
            }
        }

        return Object.entries(fileData).map(([fileName, data]) => {
            return {
                filePath: fileName,
                coverage: data.total === 0 ? 100 : (data.covered / data.total) * 100,
                details: data.missingBlocks.length > 0 ? `Uncovered blocks: ${data.missingBlocks.slice(0, 5).join(', ')}${data.missingBlocks.length > 5 ? '...' : ''}` : undefined
            };
        });
    }

    static parsePython(jsonPath: string): FileCoverage[] {
        if (!fs.existsSync(jsonPath)) return [];
        const data = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
        const results: FileCoverage[] = [];

        if (data.files) {
            for (const filePath in data.files) {
                const fileStat = data.files[filePath];
                results.push({
                    filePath,
                    coverage: fileStat.summary.percent_covered,
                    details: fileStat.missing_lines?.length > 0 ? `Missing lines: ${fileStat.missing_lines.slice(0, 10).join(', ')}${fileStat.missing_lines.length > 10 ? '...' : ''}` : undefined
                });
            }
        }
        return results;
    }

    static parseJacoco(xmlPath: string): FileCoverage[] {
        if (!fs.existsSync(xmlPath)) return [];
        const content = fs.readFileSync(xmlPath, 'utf8');
        const results: FileCoverage[] = [];

        // Basic regex parsing for JaCoCo XML if no XML parser available
        // <sourcefile name="StringUtils.java"> ... <counter type="LINE" missed="10" covered="20"/>
        const sourceFileMatches = content.matchAll(/<sourcefile name="([^"]+)">[\s\S]*?<counter type="LINE" missed="(\d+)" covered="(\d+)"\/>/g);

        for (const match of sourceFileMatches) {
            const fileName = match[1];
            const missed = parseInt(match[2], 10);
            const covered = parseInt(match[3], 10);
            const total = missed + covered;
            results.push({
                filePath: fileName,
                coverage: total === 0 ? 100 : (covered / total) * 100
            });
        }
        return results;
    }
}

import datetime
import uuid
import re

class PaymentService:
    """
    PaymentService - A service to manage transactions and validate payments.
    This class is used to test AI Test Generation for Python.
    """

    def __init__(self):
        self.transactions = {}
        self.supported_methods = ["CREDIT_CARD", "DEBIT_CARD", "PAYPAL", "CRYPTO"]
        self.min_payment = 1.0
        self.max_payment = 10000.0

    def process_payment(self, amount: float, method: str, currency: str = "USD"):
        """
        Validates and processes a payment request.
        """
        if amount < self.min_payment:
            raise ValueError(f"Amount {amount} is below the minimum payment of {self.min_payment}")

        if amount > self.max_payment:
            raise ValueError(f"Amount {amount} exceeds the maximum payment of {self.max_payment}")

        if method.upper() not in self.supported_methods:
            raise ValueError(f"Payment method {method} is not supported. Supported: {self.supported_methods}")

        if not re.match(r"^[A-Z]{3}$", currency.upper()):
            raise ValueError("Invalid currency format. Must be a 3-letter ISO code.")

        transaction_id = str(uuid.uuid4())
        fee = self.calculate_fees(amount, method)
        total = amount + fee

        transaction = {
            "id": transaction_id,
            "amount": amount,
            "fee": fee,
            "total": total,
            "method": method.upper(),
            "currency": currency.upper(),
            "timestamp": datetime.datetime.now().isoformat(),
            "status": "COMPLETED"
        }

        self.transactions[transaction_id] = transaction
        return transaction

    def calculate_fees(self, amount: float, method: str) -> float:
        """
        Calculates transaction fees based on the payment method.
        """
        method = method.upper()
        if method == "CREDIT_CARD":
            return amount * 0.03 + 0.30
        elif method == "DEBIT_CARD":
            return amount * 0.01 + 0.10
        elif method == "PAYPAL":
            return amount * 0.04
        elif method == "CRYPTO":
            return amount * 0.005
        else:
            return 0.0

    def get_transaction(self, transaction_id: str):
        """
        Retrieves a transaction by its unique ID.
        """
        return self.transactions.get(transaction_id)

    def refund_payment(self, transaction_id: str):
        """
        Refunds a completed transaction.
        """
        if transaction_id not in self.transactions:
            return False

        transaction = self.transactions[transaction_id]
        if transaction["status"] == "REFUNDED":
            return False

        # Check if transaction is within the 30-day refund window
        tx_time = datetime.datetime.fromisoformat(transaction["timestamp"])
        if (datetime.datetime.now() - tx_time).days > 30:
            return False

        transaction["status"] = "REFUNDED"
        return True

    def get_total_volume(self, method: str = None):
        """
        Calculates total volume, optionally filtered by method.
        """
        total = 0.0
        for tx in self.transactions.values():
            if method is None or tx["method"] == method.upper():
                if tx["status"] != "REFUNDED":
                    total += tx["amount"]
        return total

    def validate_card_number(self, card_number: str) -> bool:
        """
        Simple Luhn algorithm check for credit card numbers.
        """
        if not card_number.isdigit():
            return False

        digits = [int(d) for d in card_number]
        checksum = 0
        reverse_digits = digits[::-1]

        for i, digit in enumerate(reverse_digits):
            if i % 2 == 1:
                digit *= 2
                if digit > 9:
                    digit -= 9
            checksum += digit

        return checksum % 10 == 0

package com.aitestgen.services;

import java.util.*;
import java.util.stream.Collectors;

/**
 * OrderService - A services class to test AI Test Generation.
 * This class contains business logic for processing orders, calculating discounts,
 * and managing inventory status.
 */
public class OrderService {

    private final Map<String, Double> productPrices = new HashMap<>();
    private final List<Order> orderHistory = new ArrayList<>();

    public OrderService() {
        // Initialize with dummy data
        productPrices.put("LAPTOP", 1200.0);
        productPrices.put("PHONE", 800.0);
        productPrices.put("TABLET", 450.0);
        productPrices.put("MONITOR", 300.0);
        productPrices.put("KEYBOARD", 50.0);
    }

    public Order createOrder(String customerName, List<String> products) {
        if (customerName == null || customerName.trim().isEmpty()) {
            throw new IllegalArgumentException("Customer name cannot be empty");
        }
        if (products == null || products.isEmpty()) {
            throw new IllegalArgumentException("Order must contain at least one product");
        }

        double totalAmount = 0;
        List<String> validProducts = new ArrayList<>();

        for (String product : products) {
            if (productPrices.containsKey(product)) {
                totalAmount += productPrices.get(product);
                validProducts.add(product);
            }
        }

        double discount = calculateDiscount(totalAmount, customerName);
        double finalAmount = totalAmount - discount;

        Order order = new Order(
            UUID.randomUUID().toString(),
            customerName,
            validProducts,
            totalAmount,
            discount,
            finalAmount,
            new Date()
        );

        orderHistory.add(order);
        return order;
    }

    private double calculateDiscount(double amount, String customerName) {
        double discount = 0;

        // Loyalty discount
        long previousOrders = orderHistory.stream()
            .filter(o -> o.getCustomerName().equals(customerName))
            .count();

        if (previousOrders > 5) {
            discount += amount * 0.15; // 15% for loyal customers
        } else if (previousOrders > 2) {
            discount += amount * 0.05; // 5% for returning customers
        }

        // Seasonal bulk discount
        if (amount > 2000) {
            discount += amount * 0.10; // Extra 10% for large orders
        }

        return discount;
    }

    public List<Order> getOrdersByCustomer(String customerName) {
        return orderHistory.stream()
            .filter(o -> o.getCustomerName().equalsIgnoreCase(customerName))
            .collect(Collectors.toList());
    }

    public boolean cancelOrder(String orderId) {
        Optional<Order> order = orderHistory.stream()
            .filter(o -> o.getId().equals(orderId))
            .findFirst();

        if (order.isPresent()) {
            Order o = order.get();
            if (isOrderEligibleForCancellation(o)) {
                return orderHistory.remove(o);
            }
        }
        return false;
    }

    private boolean isOrderEligibleForCancellation(Order order) {
        long diffInMillies = Math.abs(new Date().getTime() - order.getCreatedAt().getTime());
        long diffInHours = diffInMillies / (60 * 60 * 1000);

        // Orders can only be cancelled within 24 hours
        return diffInHours < 24;
    }

    public double getTotalRevenue() {
        return orderHistory.stream()
            .mapToDouble(Order::getFinalAmount)
            .sum();
    }

    // Inner DTO Class
    public static class Order {
        private final String id;
        private final String customerName;
        private final List<String> products;
        private final double totalAmount;
        private final double discount;
        private final double finalAmount;
        private final Date createdAt;

        public Order(String id, String customerName, List<String> products, 
                     double totalAmount, double discount, double finalAmount, Date createdAt) {
            this.id = id;
            this.customerName = customerName;
            this.products = products;
            this.totalAmount = totalAmount;
            this.discount = discount;
            this.finalAmount = finalAmount;
            this.createdAt = createdAt;
        }

        public String getId() { return id; }
        public String getCustomerName() { return customerName; }
        public List<String> getProducts() { return products; }
        public double getTotalAmount() { return totalAmount; }
        public double getDiscount() { return discount; }
        public double getFinalAmount() { return finalAmount; }
        public Date getCreatedAt() { return createdAt; }
    }
}

